import{_ as e,c as t,o as p,ah as S}from"./chunks/framework.BxT5r71R.js";const s=JSON.parse('{"title":"SKY-HI谈MAZZEL：新一轮选秀希望实现什么","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/9_SKY-HI谈MAZZEL：新一轮选秀希望实现什么.md","filePath":"zh-cn/Management2/PART2/9_SKY-HI谈MAZZEL：新一轮选秀希望实现什么.md"}'),r={name:"zh-cn/Management2/PART2/9_SKY-HI谈MAZZEL：新一轮选秀希望实现什么.md"};function n(o,a,M,E,I,i){return p(),t("div",null,[...a[0]||(a[0]=[S('<p>► 2023年4月</p><h2 id="sky-hi谈mazzel-新一轮选秀希望实现什么" tabindex="-1">SKY-HI谈MAZZEL：新一轮选秀希望实现什么 <a class="header-anchor" href="#sky-hi谈mazzel-新一轮选秀希望实现什么" aria-label="Permalink to &quot;SKY-HI谈MAZZEL：新一轮选秀希望实现什么&quot;">​</a></h2><p>#MAZZEL #良好的氛围 #话题热度 #守护与进取 #职业自觉</p><h3 id="我觉得-爆红-与-哑火-往往只有一线之隔。比起制造更大的话题热度-我更在意如何-守护-。" tabindex="-1">“我觉得，‘爆红’与‘哑火’往往只有一线之隔。比起制造更大的话题热度，我更在意如何‘守护’。” <a class="header-anchor" href="#我觉得-爆红-与-哑火-往往只有一线之隔。比起制造更大的话题热度-我更在意如何-守护-。" aria-label="Permalink to &quot;“我觉得，‘爆红’与‘哑火’往往只有一线之隔。比起制造更大的话题热度，我更在意如何‘守护’。”&quot;">​</a></h3><p><strong>2023年5月17日，MAZZEL正式出道，成为BMSG继BE:FIRST之后推出的第二支组合。从3月的出道记者会算起，不到一个月里，我们曾数次与SKY-HI见面。他依然忙碌不已，看上去正精力充沛地迎接各种挑战。不过，一谈起MAZZEL，他似乎就格外神采奕奕，笑得十分开心。聊起他们在电视节目中的表演和工作现场的表现，他总会说“很开心”“太棒了”，欣喜于每次见到他们时的新成长。</strong></p><p>昨天我也去了MAZZEL的工作现场。现在，成员之间的氛围真的非常好。这次项目启动时，我们已经与环球音乐（Universal Music）等合作方建立了良好的合作关系，大家从一开始就积极投入。这一点与THE FIRST时期的公司状况完全不同。所以，现场的氛围也特别好。MAZZEL上台表演前，大家会一边说“去吧！”，一边鼓掌送他们上台。在这样温暖的氛围中，艺人也能开开心心地表演。我想一遍又一遍地对MAZZEL说：“你们现在真的很棒，谢谢你们。”希望通过反复传达这份肯定，让他们也能更加确信：“这个方向是对的。”</p><h3 id="避开的-爆红-与-哑火" tabindex="-1">避开的“爆红”与“哑火” <a class="header-anchor" href="#避开的-爆红-与-哑火" aria-label="Permalink to &quot;避开的“爆红”与“哑火”&quot;">​</a></h3><p><strong>MAZZEL的诞生企划《MISSIONx2》（以下简称《Mx2》）于2022年春启动。上一轮选秀THE FIRST曾与地面电视节目《Sukkiri》等合作，这一次则选择仅在BMSG YouTube官方频道播出。而且，节目第一集就揭晓了最终入选MAZZEL的成员，这在淘汰赛制的选秀节目中十分少见。如今《Mx2》已经结束，我们首先请他回顾了这次尝试。</strong></p><p>无论是优势还是不足，我的感受都是，确实“和预想的一样”。不足之处是，节目很难覆盖更广泛的人群。而且，第一集就公布了出道成员，节目也不是靠悬念和紧张感吸引关注的。</p><p>不过，考虑到BMSG当时所处的发展阶段，这档节目确实更侧重“守护”。《Mx2》项目启动时，BE:FIRST出道才半年左右，公司需要以BE:FIRST为核心，站稳脚跟。从《Bye-Good-Bye》前后开始，他们的成绩开始让人感到安心。接下来是发行风格强劲、很酷的歌曲，再到专辑《BE:1》、BMSG FES&#39;22、首次剧场巡演，以及我们争取登上的《NHK红白歌会》。他们接下来的成长路径已经相当清晰，我们也很有把握。</p><p>综合考虑下来，我们很看重的一点，就是避免项目和参与者遭遇意外状况或受到负面影响。我觉得，buzz（爆红）和bomb（哑火）往往只有一线之隔。无论是BE:FIRST、即将以MAZZEL的身份走向大众的他们，还是支持他们的人，当时都已经能开开心心、积极向前。所以，比起制造更大的话题热度，我更在意的是“守护”，避免他们受到伤害。尤其是选秀节目，一旦采用淘汰赛制，就很容易出现“节目成功＝观众争吵不休”的局面。即使THE FIRST原本就选择尽量避开这条路，也还是出现了不少我们不愿看到的纷争。</p><p>当然，这并不意味着整家公司都转向了“守护”。像D.U.N.K.这样主动出击的项目，我们也在不断推进（笑）。</p><p>2022年11月22日，BMSG在YouTube直播记者会，同时观看人数达到了约10万。MAZZEL是BMSG推出的第二支组合，已经有了一定的公众关注度和数据基础，我们才更有底气侧重“守护”。</p><p>再补充一点，我也希望MAZZEL正式走向大众之后，《Mx2》能一直留在网上，继续起到宣传他们的作用。我觉得，即使到了3年后，这档节目也很有可能继续为MAZZEL带来积极影响。</p><h3 id="对经历过the-first的ran的期许" tabindex="-1">对经历过THE FIRST的RAN的期许 <a class="header-anchor" href="#对经历过the-first的ran的期许" aria-label="Permalink to &quot;对经历过THE FIRST的RAN的期许&quot;">​</a></h3><p>项目最初的参加者，是在THE FIRST结束后成为BMSG练习生（trainee）的RAN和REIKO（集训前退出选秀），以及于2021年冬加入的KAIRYU和SEITO。他们从项目启动的2022年3月起持续接受训练。随后，通过练习生招募选秀的候选人加入，BMSG第二支组合的成员选拔正式展开。参赛者各自所处的阶段不同，SKY-HI最初的任务之一，就是正视这种环境的敏感之处，并妥善应对。</p><p>《Mx2》所有参加集训的人都认识RAN，这毕竟不同于普通的人际交往。身处其中，还要尽量不露怯，我想RAN一定会感到不安。对此，我当然也很过意不去。可即便如此，集训初期仍然需要他站出来带领大家，这无疑非常辛苦。</p><p>此前一直以练习生身份接受培养的参赛者，自然更有优势。他们有时间思考以音乐为职业意味着什么，也有条件朝这个方向努力。尤其是RAN，曾在THE FIRST FINAL和BMSG FES上面对上万名观众表演，是唯一能够具体想象自己未来模样的参赛者。想象得越具体，就越容易实现，这也是一种优势。</p><p>不只是RAN，任何人把注意力放在自己的成长上，就不会那么在意周围人的情况。我一直希望，RAN能单纯地想着“我要成为优秀的艺人”“我要成为更好的人”。但我也知道，这并不容易。所以，最后他真的做到了，我真的特别高兴。</p><p><strong>《Mx2》安排了媒体素养等理论课程，这也是THE FIRST所没有的特色。</strong> 其实在THE FIRST时期，就已经有过这样的想法，只是当时还顾不上。这次，BMSG和我有了BE:FIRST与THE FIRST的成功经验，说话也更有说服力。我想，这也是课程得以落实的原因之一。</p><p>两次选秀的参赛者也有所不同。THE FIRST到了最后阶段，已经没有人只把出道当作目标了，这当然是件好事。大家关注的是出道后还能成长多少，我也一直在引导他们往这个方向思考。不过，THE FIRST结束后，可能会有更多人因为“BE:FIRST好酷”“我想在BMSG出道”，而把出道本身当成终点。我觉得，这种可能性并不低。正因如此，他们需要尽早建立职业自觉，而这通常需要作为专业艺人历练几年，才能逐渐形成。</p><p><strong>在3月30日的出道记者会上，许多成员回顾选秀时，都谈到了“为人处世方面的成长”，这一点令人印象深刻。想必，这是他们经历种种之后的切身体会。那么，训练过程中是否也着重培养了这方面的素养？不过，SKY-HI表示，要谈到公众对他们这方面成长的认可，现在还为时尚早。</strong></p><h3 id="现在评价人格素养-还为时尚早" tabindex="-1">现在评价人格素养，还为时尚早 <a class="header-anchor" href="#现在评价人格素养-还为时尚早" aria-label="Permalink to &quot;现在评价人格素养，还为时尚早&quot;">​</a></h3><p>怎样才能提升一个人的人格素养、促进心态成熟，其实我自己也很想知道（笑）。不过，这也是我作为社长深感责任重大的一部分。</p><p>最初我并没有特别意识到这一点，但THE FIRST有一个积极的变化：我一直尽量在表演前后认真、耐心地与参赛者沟通，结果大家之间也逐渐形成了认真交流、彼此尊重的文化。</p><p>到了《MISSIONx2》，因为我与他们相处的时间并不长，所以我认为，见面时提供心理安全感，是我的重要职责之一。大多数成员还在学生年纪，能与让他们感到安心的成年人相处，我想很重要。</p><p>不过，说到教育，我确实觉得，如果本人不主动投入，就很难有意义。对于别人强加的教育，人往往很难积极对待。比如，有些很棒的寺院，长大后哪怕特意挤出假期也想去看看，可学生时代跟着学校去修学旅行，参观时却只觉得“好没劲啊”，不是吗（笑）？这么想来，如果大家和我聊过之后都能提起精神，那么即使不见面，他们或许也会比较积极地投入各项课程。我确实有过这样的想法，但仅凭这些，我不认为就能说自己“培养了他们的人格素养”。</p><p>另外，要判断“他们的人格素养已经有所成长”，包括BE:FIRST在内，现在都还为时尚早。我觉得，这不是可以轻易下结论的事，而且他们还很年轻。他们要在言行中展现出高度成熟的社会性，并因此赢得公众认可，我想还需要时间。</p><p>当然，一个人将来能否成长为优秀的人，能否主动努力、争取成为更好的自己，我想也与个人潜质有关。所以，在评审阶段，我也会不自觉地留意这些方面。他们现在的人格素养已经很好，这是大前提。不过，要达到足以赢得公众认可的高度，我想还是以后的事。他们具备这样的成长潜质，我也希望他们继续朝这个方向成长。现阶段，我能说的就是这些。</p><p><strong>据他介绍，组合的8人编制，是在最终评审过程中确定的。组合通常会选择奇数编制，单从队形编排来说更方便。不过，在MAZZEL身上，他也看到了另一种未来：每位成员的鲜明个性如果都能自然发挥，就有望组成一支独一无二的团队。</strong></p><p>选择偶数编制，是出于非常积极的理由。我看每个人表演时，都会想象他们几年后的样子。我发现，很多人都会“因为另一个人的存在而更加闪耀”。这是非常美好的事，我不想忽视它。</p><p>介绍组合时，经常会说“成员个性各不相同”。MAZZEL当然也是如此，但我觉得，他们的个性或许能以一种独特的方式共存。成员之间的差异比通常所说的“各不相同”还要大，却不必刻意安排，自然就能组成这样的团队。这正是BMSG的理念：我觉得，只要他们按照自己的意愿去做，或许就能自然呈现出一种仿佛经过精心设计的多样性。我觉得，这也会成为他们未来的一大优势。</p><h3 id="令人好奇的-bmsg-巧思" tabindex="-1">令人好奇的“BMSG”巧思…… <a class="header-anchor" href="#令人好奇的-bmsg-巧思" aria-label="Permalink to &quot;令人好奇的“BMSG”巧思……&quot;">​</a></h3><p><strong>从预出道曲《MISSION》的表演中，已经能看出成员们各自鲜明的个性，以及他们自然而然凝聚成团队的样子。这支组合似乎蕴藏着一股难以捉摸的爆发力。而出道曲《Vivid》又呈现出与《MISSION》截然不同的风格，令人惊讶。另一个令人好奇的问题是：他们的作品是否也像BE:FIRST的歌曲那样，藏着与BMSG这4个字母有关的巧思？</strong></p><p>创作《MISSION》时，我想为准备参加选秀的人加油。当然，它也是送给MAZZEL的应援歌。写歌词时，我希望听歌的人和唱歌的人能从中看到不同的景象，我觉得自己做到了。比如，RAN开口唱出“期盼已久的时刻终于到来”时，就特别令人感动，而最后，同一句歌词由KAIRYU唱出。我觉得，“等待”真的是一件很难熬的事。而他们之所以一直在等，我自己也是原因之一。这一年多来，我始终怀着一种近乎祈愿的心情，这部分歌词也寄托着那份祈愿。</p><p>至于《Vivid》，要说它很有出道曲的感觉，确实如此。不过，就像BE:FIRST从《Shining One》到《Gifted.》一样，我很看重它与《MISSION》之间的氛围变化。</p><p>请不要因为MAZZEL的歌名首字母没有对应“BMSG”这4个字母，就觉得奇怪（笑）。当初在BE:FIRST的作品中有意识地这样安排，是因为那是专辑《BE:1》的概念。BE:FIRST体现了BMSG每个字母所蕴含的意义，也亲自证明（PROOF）了：包括BESTY在内，每一个人都是最棒的存在。至此，这一概念的表达就暂告完成。</p><p>不过，要说MAZZEL“没有”类似的设计，可能也还为时尚早（笑）。说不定会有。我觉得，还要看他们的专辑完成时是什么样子。</p>',38)])])}const Z=e(r,[["render",n]]);export{s as __pageData,Z as default};
